package main

import (
	&quot;fmt&quot;
	&quot;strings&quot;
)

type BlockParserState struct {
	pendingTag string &#47;&#47; 暂存的不完整标签前缀
	thinking   bool   &#47;&#47; 当前是否在  块内
	inlineCode bool
}

func stripBlockTags(delta string, state BlockParserState) (string, BlockParserState) {
	output := &quot;&quot;
	i := 0

	&#47;&#47; 拼接上一次剩下的不完整标签
	if len(state.pendingTag) &gt; 0 {
		delta = state.pendingTag + delta
		state.pendingTag = &quot;&quot;
	}

	&#47;&#47; ---------------- FIX 核心修复 ----------------
	&#47;&#47; 把字符串转成 rune 切片，支持中文&#47;多字节字符
	runes := []rune(delta)
	n := len(runes)

	for i &lt; n {
		c := runes[i]

		&#47;&#47; 行内代码 `
		if c == &#39;`&#39; {
			state.inlineCode = !state.inlineCode
			output += string(c)
			i++
			continue
		}

		&#47;&#47; 行内代码模式，直接输出
		if state.inlineCode {
			output += string(c)
			i++
			continue
		}

		&#47;&#47; 匹配标签 &lt;xxx
		if c == &#39;&lt;&#39; {
			&#47;&#47; 取当前位置到末尾的字符串（用于判断前缀）
			remain := string(runes[i:])

			&#47;&#47; 匹配
			if strings.HasPrefix(remain, &quot;&lt;think&gt;&quot;) {
				state.thinking = true
				i += 7 &#47;&#47; 跳过
				continue
			}

			&#47;&#47; 匹配
			if strings.HasPrefix(remain, &quot;&lt;&#47;think&gt;&quot;) {
				state.thinking = false
				i += 8 &#47;&#47; 跳过
				continue
			}

			&#47;&#47; 不完整标签，暂存等待下一个 delta
			if strings.HasPrefix(&quot;&lt;think&gt;&quot;, remain) || strings.HasPrefix(&quot;&lt;&#47;think&gt;&quot;, remain) {
				state.pendingTag = remain
				break &#47;&#47; 停止本次解析
			}
		}

		&#47;&#47; 不在思考中，才输出
		if !state.thinking {
			output += string(c)
		}

		i++
	}

	return output, state
}

func main() {
	delta1 := &quot;最终答案是：&lt;think&gt;让我分析一下这个问题首先考虑边界条&quot;
	delta2 := &quot;件...因此结论是&lt;&#47;think&quot;
	delta3 := &quot;&gt;最终答案是42&quot;

	deltas := []string{delta1, delta2, delta3}
	state := BlockParserState{}

	fmt.Println(&quot;=== 流式解析结果 ===&quot;)
	for idx, d := range deltas {
		out, s := stripBlockTags(d, state)
		state = s
		fmt.Printf(&quot;Delta %d → 输出: %q\n&quot;, idx+1, out)
	}
}
